// Every credential here is generated by the test; nothing reads a real one, and nothing reaches a
// real service: upstreams are local TLS servers that a fake resolver maps names to.

func token(t *testing.T) string {
	t.Helper()
	b := make([]byte, 20)
	if _, err := rand.Read(b); err != nil {
		t.Fatal(err)
	}
	return "test_" + hex.EncodeToString(b)
}

type creds map[string]string

func (c creds) Credential(_ context.Context, org, name string) ([]byte, error) {
	v, ok := c[org+"/"+name]
	if !ok {
		return nil, errors.New("no such credential")
	}
	return []byte(v), nil
}

// resolver maps names to addresses and counts lookups.
type resolver struct {
	mu    sync.Mutex
	hosts map[string][]netip.Addr
	calls int
}

func (r *resolver) LookupNetIP(_ context.Context, _, host string) ([]netip.Addr, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.calls++
	a, ok := r.hosts[host]
	if !ok {
		return nil, errors.New("no such host")
	}
	return a, nil
}

// upstream is a local TLS server standing in for a service: it records what it received and
// answers by path.
type upstream struct {
	srv   *httptest.Server
	mu    sync.Mutex
	got   []*http.Request
	hits  int
	reply func(w http.ResponseWriter, r *http.Request)
}

func newUpstream(t *testing.T) *upstream {
	t.Helper()
	u := &upstream{}
	u.srv = httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u.mu.Lock()
		u.hits++
		u.got = append(u.got, r.Clone(context.Background()))
		reply := u.reply
		u.mu.Unlock()
		if reply != nil {
			reply(w, r)
			return
		}
		switch r.URL.Path {
		case "/echo":
			// An upstream that reflects the request's credential back, as some error pages do.
			w.Header().Set("X-Echo", r.Header.Get("Authorization"))
			io.WriteString(w, "you sent: "+r.Header.Get("Authorization")+" cookie="+r.Header.Get("Cookie"))
		default:
			io.WriteString(w, "ok "+r.Method+" "+r.URL.RequestURI())
		}
	}))
	t.Cleanup(u.srv.Close)
	return u
}

func (u *upstream) port() string {
	_, port, _ := strings.Cut(strings.TrimPrefix(u.srv.URL, "https://"), ":")
	return port
}

func (u *upstream) count() int {
	u.mu.Lock()
	defer u.mu.Unlock()
	return u.hits
}

func (u *upstream) last() *http.Request {
	u.mu.Lock()
	defer u.mu.Unlock()
	return u.got[len(u.got)-1]
}

type fixture struct {
	t     *testing.T
	store *eventstore.Store
	up    *upstream
	res   *resolver
	tok   string
	gw    *gateway.Gateway
	front *httptest.Server
}

var loopback = netip.MustParseAddr("127.0.0.1")

// testAddresses allows the local test upstream's address and applies PublicOnly to every other.
func testAddresses(a netip.Addr) error {
	if a.Unmap() == loopback {
		return nil
	}
	return gateway.PublicOnly(a)
}

func open(t *testing.T, tweak func(*gateway.Config)) *fixture {
	t.Helper()
	dir := t.TempDir()
	reg, err := eventstore.NewRegistry(append(gateway.Payloads(), policy.DecisionRecord{})...)
	if err != nil {
		t.Fatal(err)
	}
	st, err := eventstore.Open(context.Background(), filepath.Join(dir, "lucy", "lucy.db"), eventstore.Options{
		Registry: reg, Projectors: []eventstore.Projector{audit.Projector{}}, SnapshotDir: filepath.Join(dir, "lucy", "state")})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { st.Close() })
	f := &fixture{t: t, store: st, up: newUpstream(t), tok: token(t),
		res: &resolver{hosts: map[string][]netip.Addr{"example.com": {loopback}}}}
	pool := x509.NewCertPool()
	pool.AddCert(f.up.srv.Certificate())
	cfg := gateway.Config{
		Org: "acme", Store: st, Resolver: f.res, Addresses: testAddresses, TLS: &tls.Config{RootCAs: pool},
		Credentials: creds{"acme/github": f.tok},
		Routes: []gateway.Route{{
			Name: "github", Upstream: "https://example.com:" + f.up.port(), Credential: "github", Scope: "repo:acme/web",
			Prefix: "Bearer ",
			Allow: []gateway.Rule{{Methods: []string{"GET"}, Path: "/repos/acme/web"}, {Methods: []string{"GET", "POST"}, Path: "/echo"},
				{Methods: []string{"GET"}, Path: "/redirect"}},
		}},
	}
	if tweak != nil {
		tweak(&cfg)
	}
	if f.gw, err = gateway.New(cfg); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(f.gw.Close)
	f.front = httptest.NewServer(f.gw)
	t.Cleanup(f.front.Close)
	return f
}

// call sends a worker's request to the gateway, as a raw path so nothing normalises it first.
func (f *fixture) call(method, rawPath string, hdr http.Header) (int, http.Header, string) {
	f.t.Helper()
	req, err := http.NewRequest(method, f.front.URL, nil)
	if err != nil {
		f.t.Fatal(err)
	}
	req.URL.Opaque = rawPath
	for k, vs := range hdr {
		req.Header[k] = vs
	}
	client := &http.Client{CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	resp, err := client.Do(req)
	if err != nil {
		f.t.Fatal(err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, resp.Header, string(b)
}

// events returns the gateway stream's event types, and fails if any event anywhere in the log
// holds the credential.
func (f *fixture) events() []string {
	f.t.Helper()
	all, err := f.store.ReadAfter(context.Background(), 0, 10000)
	if err != nil {
		f.t.Fatal(err)
	}
	var types []string
	for _, e := range all {
		if bytes.Contains(e.Payload, []byte(f.tok)) {
			f.t.Fatalf("event %d (%s) holds the credential", e.Seq, e.Type)
		}
		if e.Stream == gateway.Stream("acme") {
			types = append(types, e.Type)
		}
	}
	return types
}

func (f *fixture) lastGateway() eventstore.Event {
	f.t.Helper()
	evs, err := f.store.ReadStream(context.Background(), gateway.Stream("acme"), 0, 10000)
	if err != nil || len(evs) == 0 {
		f.t.Fatalf("gateway stream: %v, %v", evs, err)
	}
	return evs[len(evs)-1]
}

func TestForwardsWithTheCredential(t *testing.T) {
	f := open(t, nil)
	status, _, body := f.call("GET", "/github/repos/acme/web/pulls?state=open",
		http.Header{"Authorization": {"Bearer worker-supplied"}, "Cookie": {"session=worker"}, "X-Forwarded-For": {"10.0.0.9"}})
	if status != 200 || body != "ok GET /repos/acme/web/pulls?state=open" {
		t.Fatalf("status %d body %q", status, body)
	}
	got := f.up.last()
	if got.Header.Get("Authorization") != "Bearer "+f.tok {
		t.Errorf("the upstream got Authorization %q, not the route's credential", got.Header.Get("Authorization"))
	}
	if got.Header.Get("Cookie") != "" || got.Header.Get("X-Forwarded-For") != "" {
		t.Errorf("the worker's own credential headers reached the upstream: %v", got.Header)
	}
	if got.Host != "example.com:"+f.up.port() {
		t.Errorf("Host %q", got.Host)
	}
	types := f.events()
	if strings.Join(types, ",") != "gateway.forwarded,gateway.completed" {
		t.Fatalf("gateway events %v", types)
	}
	decs, err := f.store.ReadStream(context.Background(), policy.Stream, 0, 10)
	if err != nil || len(decs) != 1 {
		t.Fatalf("policy decisions %v, %v", decs, err)
	}
	d, err := eventstore.DecodeAs[policy.DecisionRecord](f.store.Registry(), decs[0])
	if err != nil || d.Outcome != policy.Cleared || d.Rule != "credential.gateway-only" || d.Kind != policy.KindCredentialUse ||
		d.Actor.Role != policy.RoleGateway || d.Target.Resource != "github" || !d.Tainted {
		t.Fatalf("decision %+v, %v", d, err)
	}
}

// LUCY-CRED-005: a credential the upstream reflects never reaches the worker, in the body or a
// header, however the body arrives.
func TestScrubsAnEchoedCredential(t *testing.T) {
	f := open(t, nil)
	status, hdr, body := f.call("GET", "/github/echo", http.Header{"Cookie": {"c=1"}})
	if status != 200 || strings.Contains(body, f.tok) || strings.Contains(hdr.Get("X-Echo"), f.tok) {
		t.Fatalf("the credential reached the worker: status %d header %q body %q", status, hdr.Get("X-Echo"), body)
	}
	if body != "you sent: Bearer "+gateway.Redacted+" cookie=" || hdr.Get("X-Echo") != "Bearer "+gateway.Redacted {
		t.Errorf("body %q header %q", body, hdr.Get("X-Echo"))
	}
	f.events()
	c, err := eventstore.DecodeAs[gateway.Completed](f.store.Registry(), f.lastGateway())
	if err != nil || c.Status != 200 || c.Scrubbed != 2 {
		t.Errorf("completed %+v, %v", c, err)
	}
}

// LUCY-CRED-005: a worker cannot ask for the echo in a shape the scrubber cannot read: an encoded
// body is refused, and a byte range is never asked of the upstream.
func TestEchoInAnEncodingIsRefused(t *testing.T) {
	f := open(t, nil)
	f.up.reply = func(w http.ResponseWriter, r *http.Request) {
		// An echo upstream that honours whatever encoding it is asked for, and gzips regardless
		// when asked for nothing it knows.
		var buf bytes.Buffer
		zw := gzip.NewWriter(&buf)
		io.WriteString(zw, "you sent: "+r.Header.Get("Authorization"))
		zw.Close()
		w.Header().Set("Content-Encoding", "gzip")
		w.Write(buf.Bytes())
	}
	status, hdr, body := f.call("GET", "/github/echo", http.Header{"Accept-Encoding": {"gzip, br, zstd"}})
	if got := f.up.last().Header.Values("Accept-Encoding"); len(got) != 1 || got[0] != "identity" {
		t.Errorf("the upstream was asked for Accept-Encoding %q", got)
	}
	if status != http.StatusBadGateway || hdr.Get("Content-Encoding") != "" {
		t.Fatalf("status %d, Content-Encoding %q", status, hdr.Get("Content-Encoding"))
	}
	if strings.Contains(body, f.tok) {
		t.Fatal("the credential reached the worker")
	}
	if zr, err := gzip.NewReader(strings.NewReader(body)); err == nil {
		if b, _ := io.ReadAll(zr); strings.Contains(string(b), f.tok) {
			t.Fatal("the credential reached the worker compressed")
		}
	}
	f.events()
	c, err := eventstore.DecodeAs[gateway.Completed](f.store.Registry(), f.lastGateway())
	if err != nil || c.Status != 200 || c.Error == "" {
		t.Errorf("completed %+v, %v", c, err)
	}
}

func TestEchoInByteRangesIsNotAsked(t *testing.T) {
	f := open(t, nil)
	f.up.reply = func(w http.ResponseWriter, r *http.Request) {
		// An echo upstream that honours Range, so a slice could split the credential.
		http.ServeContent(w, r, "", time.Time{}, strings.NewReader("you sent: "+r.Header.Get("Authorization")))
	}
	full := len("you sent: Bearer ") + len(f.tok)
	var got strings.Builder
	for start := 0; start < full; start += 8 {
		status, _, body := f.call("GET", "/github/echo", http.Header{"Range": {fmt.Sprintf("bytes=%d-%d", start, start+7)}})
		if status != 200 {
			t.Fatalf("bytes from %d: status %d; the range reached the upstream", start, status)
		}
		got.WriteString(body)
	}
	if strings.Contains(got.String(), f.tok) || strings.Contains(got.String(), f.tok[:len(f.tok)/2]) {
		t.Fatal("the credential reached the worker in slices")
	}
	f.call("GET", "/github/echo", http.Header{"Range": {"bytes=0-7"}, "If-Range": {`"x"`}})
	if r := f.up.last(); r.Header.Get("Range") != "" || r.Header.Get("If-Range") != "" {
		t.Errorf("the upstream got Range %q If-Range %q", r.Header.Get("Range"), r.Header.Get("If-Range"))
	}
	f.events()
}

func TestScrubberAcrossReads(t *testing.T) {
	secret := []byte("s3cr3t-value")
	in := "a s3cr3t-value b s3cr3t-values3cr3t-value c s3cr3t-valu"
	// Two secrets back to back are two replacements; a secret cut short is not one.
	want := "a " + gateway.Redacted + " b " + gateway.Redacted + gateway.Redacted + " c s3cr3t-valu"
	for name, r := range map[string]io.Reader{
		"whole":    strings.NewReader(in),
		"one byte": iotest.OneByteReader(strings.NewReader(in)),
		"half":     iotest.HalfReader(strings.NewReader(in)),
	} {
		got, err := io.ReadAll(gateway.NewScrubberForTest(r, secret))
		if err != nil || string(got) != want {
			t.Errorf("%s: %q, %v; want %q", name, got, err, want)
		}
	}
}

func TestRefusesWhatTheRouteDoesNotAllow(t *testing.T) {
	f := open(t, nil)
	for _, c := range []struct {
		method, path string
		status       int
	}{
		{"POST", "/github/repos/acme/web/pulls", 403},   // method not allowed there
		{"GET", "/github/repos/acme/other", 403},        // another repository
		{"GET", "/github/repos/acme/web-other", 403},    // a prefix that is not a segment
		{"GET", "/github/repos/acme/web/../other", 400}, // dot segments
		{"GET", "/github/repos/acme/web/%2e%2e/other", 400},
		{"GET", "/github/repos/acme/web%2f..%2fother", 400}, // encoded separators
		{"GET", "/github/repos/acme/web%5cother", 400},
		{"GET", "/github//repos/acme/web", 400}, // empty segment
		{"GET", "/nope/anything", 404},          // no such route
		{"GET", "/", 404},
	} {
		if status, _, _ := f.call(c.method, c.path, nil); status != c.status {
			t.Errorf("%s %s: status %d, want %d", c.method, c.path, status, c.status)
		}
	}
	if f.up.count() != 0 {
		t.Fatalf("the upstream was called %d times for refused requests", f.up.count())
	}
	for _, typ := range f.events() {
		if typ != "gateway.denied" {
			t.Fatalf("a refused request recorded %s", typ)
		}
	}
	if n := len(f.events()); n != 10 {
		t.Errorf("%d denials recorded, want 10", n)
	}
	if d, _ := f.store.ReadStream(context.Background(), policy.Stream, 0, 10); len(d) != 0 {
		t.Error("a refused request was decided as a credential use")
	}
}

// LUCY-CRED-001: a redirect goes back to the worker; the gateway never follows it, so the
// credential never goes to a host the route does not name.
func TestNeverFollowsARedirect(t *testing.T) {
	f := open(t, nil)
	evil := newUpstream(t)
	f.res.hosts["evil.example"] = []netip.Addr{loopback}
	f.up.reply = func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, "https://evil.example:"+evil.port()+"/steal", http.StatusFound)
	}
	status, hdr, _ := f.call("GET", "/github/redirect", nil)
	if status != http.StatusFound || !strings.HasPrefix(hdr.Get("Location"), "https://evil.example:") {
		t.Fatalf("status %d Location %q", status, hdr.Get("Location"))
	}
	if evil.count() != 0 || f.up.count() != 1 {
		t.Fatalf("the redirect was followed: evil %d, upstream %d", evil.count(), f.up.count())
	}
}

func TestPublicOnly(t *testing.T) {
	for _, s := range []string{
		"127.0.0.1", "10.1.2.3", "172.16.0.1", "192.168.1.1", "169.254.169.254", "100.100.100.200", "100.64.0.1",
		"0.0.0.0", "224.0.0.1", "255.255.255.255", "192.0.2.1", "198.18.0.1", "240.0.0.1",
		"::1", "::", "fe80::1", "fd00:ec2::254", "fc00::1", "ff02::1", "::ffff:127.0.0.1", "::ffff:10.0.0.1",
		"64:ff9b::a00:1", "2002:a00:1::", "2001:db8::1", "2001:0:4136:e378::1",
	} {
		if err := gateway.PublicOnly(netip.MustParseAddr(s)); !errors.Is(err, gateway.ErrAddressDenied) {
			t.Errorf("%s allowed", s)
		}
	}
	for _, s := range []string{"8.8.8.8", "140.82.112.3", "2606:4700::1111", "::ffff:8.8.8.8"} {
		if err := gateway.PublicOnly(netip.MustParseAddr(s)); err != nil {
			t.Errorf("%s denied: %v", s, err)
		}
	}
}

// LUCY-CRED-004: an upstream that resolves to a private, link-local or metadata address is never
// called, nor one that resolves to a mix of public and private addresses.
func TestRefusesInternalUpstreams(t *testing.T) {
	for name, addrs := range map[string][]string{
		"private":  {"10.0.0.5"},
		"metadata": {"169.254.169.254"},
		"loopback": {"127.0.0.1"},
		"mixed":    {"140.82.112.3", "10.0.0.5"},
		"ipv6 ula": {"fd00:ec2::254"},
	} {
		f := open(t, func(c *gateway.Config) { c.Addresses = nil }) // the production policy
		f.res.hosts["example.com"] = nil
		for _, a := range addrs {
			f.res.hosts["example.com"] = append(f.res.hosts["example.com"], netip.MustParseAddr(a))
		}
		if status, _, _ := f.call("GET", "/github/repos/acme/web", nil); status != http.StatusForbidden {
			t.Errorf("%s: status %d", name, status)
		}
		if f.up.count() != 0 {
			t.Errorf("%s: the upstream was called", name)
		}
		if types := f.events(); len(types) != 1 || types[0] != "gateway.denied" {
			t.Errorf("%s: events %v", name, types)
		}
	}
	f := open(t, nil)
	f.res.hosts = map[string][]netip.Addr{}
	if status, _, _ := f.call("GET", "/github/repos/acme/web", nil); status != http.StatusForbidden || f.up.count() != 0 {
		t.Errorf("an unresolvable upstream: status %d", status)
	}
}

// The name is resolved once per request and the connection goes to that checked address, so an
// answer that changes between the check and the dial is never used.
func TestResolvesOncePerRequest(t *testing.T) {
	f := open(t, nil)
	f.call("GET", "/github/repos/acme/web", nil)
	if f.res.calls != 1 {
		t.Fatalf("%d lookups for one request", f.res.calls)
	}
}

func TestFailsClosed(t *testing.T) {
	t.Run("no credential", func(t *testing.T) {
		f := open(t, func(c *gateway.Config) { c.Credentials = creds{} })
		if status, _, _ := f.call("GET", "/github/repos/acme/web", nil); status != http.StatusBadGateway || f.up.count() != 0 {
			t.Fatalf("status %d, upstream %d", status, f.up.count())
		}
		if types := f.events(); len(types) != 1 || types[0] != "gateway.denied" {
			t.Fatalf("events %v", types)
		}
	})
	t.Run("the log cannot be written", func(t *testing.T) {
		f := open(t, nil)
		if err := f.store.Close(); err != nil {
			t.Fatal(err)
		}
		if status, _, _ := f.call("GET", "/github/repos/acme/web", nil); status == http.StatusOK || f.up.count() != 0 {
			t.Fatalf("an unrecorded request was forwarded: status %d, upstream %d", status, f.up.count())
		}
	})
	t.Run("an environment proxy is ignored", func(t *testing.T) {
		t.Setenv("HTTPS_PROXY", "http://127.0.0.1:1")
		t.Setenv("HTTP_PROXY", "http://127.0.0.1:1")
		f := open(t, nil)
		if status, _, _ := f.call("GET", "/github/repos/acme/web", nil); status != 200 {
			t.Fatalf("status %d", status)
		}
	})
}

func TestConfigIsChecked(t *testing.T) {
	ok := gateway.Route{Name: "gh", Upstream: "https://api.github.com", Credential: "gh",
		Allow: []gateway.Rule{{Methods: []string{"GET"}, Path: "/"}}}
	bad := map[string]func(*gateway.Route){
		"http upstream":     func(r *gateway.Route) { r.Upstream = "http://api.github.com" },
		"user info":         func(r *gateway.Route) { r.Upstream = "https://u:p@api.github.com" },
		"a query":           func(r *gateway.Route) { r.Upstream = "https://api.github.com/?x=1" },
		"unclean base":      func(r *gateway.Route) { r.Upstream = "https://api.github.com/a/../b" },
		"no credential":     func(r *gateway.Route) { r.Credential = "" },
		"no rules":          func(r *gateway.Route) { r.Allow = nil },
		"rule without verb": func(r *gateway.Route) { r.Allow = []gateway.Rule{{Path: "/"}} },
		"relative rule":     func(r *gateway.Route) { r.Allow = []gateway.Rule{{Methods: []string{"GET"}, Path: "repos"}} },
		"bad name":          func(r *gateway.Route) { r.Name = "GH" },
		"host header":       func(r *gateway.Route) { r.Header = "Host" },
	}
	f := open(t, nil)
	for name, mod := range bad {
		r := ok
		mod(&r)
		if _, err := gateway.New(gateway.Config{Org: "acme", Store: f.store, Credentials: creds{}, Routes: []gateway.Route{r}}); err == nil {
			t.Errorf("%s: accepted", name)
		}
	}
	if _, err := gateway.New(gateway.Config{Org: "acme", Store: f.store, Credentials: creds{}, Routes: []gateway.Route{ok, ok}}); err == nil {
		t.Error("a duplicate route was accepted")
	}
	if _, err := gateway.New(gateway.Config{Org: "Acme", Store: f.store, Credentials: creds{}}); err == nil {
		t.Error("a bad org was accepted")
	}
	if _, err := url.Parse(ok.Upstream); err != nil {
		t.Fatal(err)
	}
}
